Hi, you can write it like this:

if (offset >= ei->valid_size) {
	iomap->type = IOMAP_UNWRITTEN;
} else if (offset + iomap->length > ei->valid_size) {
	iomap->length = round_up(ei->valid_size,
				 i_blocksize(inode)) -
					iomap->offset;
}

